<script setup lang="ts">import {computed} from 'vue';import type {EChartsOption} from 'echarts';import BaseChart from '@/components/BaseChart.vue';import ScreenPanel from './ScreenPanel.vue';import type {DashboardCarbon} from '@/types';const props=defineProps<{data:DashboardCarbon}>();const v=(x:number|null,d=1)=>x==null?'--':x.toFixed(d),scopeChart=computed<EChartsOption>(()=>({series:[{type:'pie',radius:['38%','68%'],data:[{name:'Scope 1',value:props.data.scope1_t},{name:'Scope 2',value:props.data.scope2_t}].filter((x):x is {name:string;value:number}=>x.value!=null)}]})),energyChart=computed<EChartsOption>(()=>({series:[{type:'pie',radius:['38%','68%'],data:Object.entries(props.data.energy).map(([name,value])=>({name,value}))}]}));</script>
<template><ScreenPanel title="碳排放总体态势" link="/carbon" :empty="data.total_t===null"><div class="screen-kpis"><div class="hero"><span>总碳排</span><b>{{v(data.total_t)}}</b><small>tCO₂</small></div><div><span>Scope 1</span><b>{{v(data.scope1_t)}}</b></div><div><span>Scope 2</span><b>{{v(data.scope2_t)}}</b></div><div><span>本月</span><b>{{v(data.month_t)}}</b></div><div><span>本年</span><b>{{v(data.year_t)}}</b></div><div><span>单位面积</span><b>{{v(data.per_area_kg_m2)}}</b><small>kgCO₂e/m²</small></div><div><span>人均</span><b>{{v(data.per_capita_t)}}</b><small>tCO₂/人</small></div></div><div class="dual-chart"><BaseChart :option="scopeChart" height="145px"/><BaseChart :option="energyChart" height="145px"/></div></ScreenPanel></template>
